import { AppComponent } from './app/app.component';
import { CalendarMonthComponent } from './app/calendar-month/calendar-month.component';
import { MonthDataService } from './app/services/month-data.service';
import { DaySummaryService, DaySummary } from './app/services/day-detail.service';
import { sentimentClass, sentimentGradient, formatTriple } from './app/utils/color-util'; // R2 reuse
import { hrefForMonth, parseViewDay, parseViewMonth, type YearMonth } from './app/utils/month-nav';
import { monthSoFarHighlights, resolveMonthHighlights } from './app/utils/month-highlights';
